export function createTeamTools(ctx) {
  const {state,api,config,esc,icon,money,fullname,drawer,close,toast,load}=ctx;
  const manage=()=>['admin','manager'].includes(state.role);
  const people=()=>state.data.masters||state.data.users.filter(u=>['groomer','master','employee'].includes(u.role));
  const input=(label,name,value='',type='text',attrs='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value??'')}" ${attrs}></label>`;
  const choices=(values,key,label,current)=>values.map(x=>`<option value="${x[key]}" ${String(current)===String(x[key])?'selected':''}>${esc(typeof label==='function'?label(x):x[label])}</option>`).join('');
  const checkChoices=(values,key,label,selected=[])=>`<div class="choice-checks">${values.map(x=>`<label><input type="checkbox" name="selection" value="${x[key]}" ${selected.includes(x[key])?'checked':''}><span>${esc(typeof label==='function'?label(x):x[label])}</span></label>`).join('')||'<p class="sub">Список пока пуст.</p>'}</div>`;
  async function saveForm(event,callback) {
    event.preventDefault();const form=event.target,button=form.querySelector('[type="submit"]');button.disabled=true;
    try{await callback(Object.fromEntries(new FormData(form)),form);}
    catch(error){const target=form.querySelector('.error');if(target)target.textContent=error.message;else toast(error.message);}
    finally{if(button.isConnected)button.disabled=false;}
  }
  function teamPage(){return `<div class="page-head"><div><div class="eyebrow">ЗНАКОМЫЕ РУКИ</div><h1>Команда <em>заботы.</em></h1><p class="sub">Мастера, их услуги и рабочие смены.</p></div>${manage()?'<button class="primary" data-team-new>Добавить мастера +</button>':''}</div><div class="card-grid">${people().map(master=>`<article class="panel service-card"><span class="avatar">${esc(master.name?.[0]||'М')}${esc(master.surname?.[0]||'')}</span><h3>${esc(fullname(master))}</h3><span class="pill green">Грумер</span><p class="sub">${(master.services||[]).length} услуг · ${state.data.book.filter(b=>b.master_id===master.user_id&&b.date===state.date).length} записей на день</p><div class="form-actions"><button class="secondary" data-team-schedule="${master.user_id}">График</button>${manage()?`<button class="secondary" data-team-edit="${master.user_id}">Профиль и услуги</button>`:''}</div></article>`).join('')||'<section class="empty"><h3>Соберём вашу команду</h3><p>Добавьте мастера и выберите услуги, которые он оказывает.</p></section>'}</div>`;}
  const weekdays=['Понедельник','Вторник','Среда','Четверг','Пятница','Суббота','Воскресенье'];
  function schedulesPage(){const schedules=state.data['work-schedules']||[];const masters=state.role==='master'?people().filter(m=>m.user_id===state.userId):people();return `<div class="page-head"><div><div class="eyebrow">СПОКОЙНЫЙ РИТМ НЕДЕЛИ</div><h1>Рабочие <em>смены.</em></h1><p class="sub">График по Москве. Свободные окошки рассчитываются сервером с учётом смен, буферов и записей.</p></div>${manage()?'<button class="primary" data-schedule-new>Добавить смену +</button>':''}</div><div class="schedule-cards">${masters.map(master=>`<section class="panel settings-card"><h2>${esc(fullname(master))}</h2><div class="schedule-week">${weekdays.map((day,index)=>{const shifts=schedules.filter(s=>s.master_id===master.user_id&&s.weekday===index);return `<div class="schedule-day"><b>${day}</b>${shifts.map(s=>`<span class="pill ${s.is_day_off?'':'green'}">${s.is_day_off?'Выходной':esc(s.start_time.slice(0,5))+'–'+esc(s.end_time.slice(0,5))}</span>${manage()?`<button class="text-btn" data-schedule-edit="${s.work_schedule_id}">Изменить</button>`:''}`).join('')||'<span class="muted">Смена не задана</span>'}</div>`}).join('')}</div></section>`).join('')||'<div class="empty">Сначала добавьте мастера.</div>'}</div>`;}
  function scheduleForm(existing={},masterId){
    if(!manage())return;
    drawer(existing.work_schedule_id?'Изменить смену':'Новая смена',`<form id="schedule-form"><label class="field">Мастер<select name="master_id" ${existing.work_schedule_id?'disabled':''}>${choices(people(),'user_id',fullname,existing.master_id||masterId)}</select></label><label class="field">День недели<select name="weekday">${weekdays.map((day,i)=>`<option value="${i}" ${existing.weekday===i?'selected':''}>${day}</option>`).join('')}</select></label><div class="form-grid">${input('Начало','start_time',existing.start_time?.slice(0,5)||'10:00','time','required')}${input('Окончание','end_time',existing.end_time?.slice(0,5)||'19:00','time','required')}</div><label class="booking-consent"><input type="checkbox" name="is_day_off" ${existing.is_day_off?'checked':''}> Выходной день</label><div class="error" role="alert"></div><button class="primary" type="submit">Сохранить смену</button>${existing.work_schedule_id?'<button class="text-btn danger" type="button" id="remove-schedule">Удалить смену</button>':''}</form>`);
    document.querySelector('#schedule-form').onsubmit=e=>saveForm(e,async(data)=>{
      if(!data.is_day_off&&data.end_time<=data.start_time)throw Error('Окончание смены должно быть позже начала.');
      await api.save('work-schedules',{master_id:existing.master_id||Number(data.master_id),weekday:Number(data.weekday),start_time:data.start_time+':00',end_time:data.end_time+':00',is_day_off:Boolean(data.is_day_off)},existing.work_schedule_id);close();await load();toast('График обновлён');
    });
    document.querySelector('#remove-schedule')?.addEventListener('click',()=>{drawer('Удалить смену?',`<p class="sub">Новые окошки на эту смену перестанут предлагаться. Существующие записи не удаляются.</p><button class="primary" id="confirm-remove-schedule">Удалить</button>`);document.querySelector('#confirm-remove-schedule').onclick=async()=>{try{await api.remove('work-schedules',existing.work_schedule_id);close();await load();toast('Смена удалена')}catch(e){toast(e.message)}}});
  }
  function masterForm(master={}){
    if(!manage())return;
    drawer(master.user_id?'Профиль мастера':'Новый мастер',`<form id="master-form"><div class="form-grid">${input('Имя','name',master.name,'text','required')}${input('Фамилия','surname',master.surname,'text','required')}</div>${input('Логин','login',master.login,'text','required autocomplete="username"')}${input(master.user_id?'Новый пароль (необязательно)':'Пароль','password','','password',`${master.user_id?'':'required'} minlength="6" autocomplete="new-password"`)}<div class="form-grid">${input('Телефон','phone',master.phone,'tel')}${input('Email','email',master.email,'email')}</div><h3 class="section-title">Услуги мастера</h3>${checkChoices(state.data.services,'service_id','title',(master.services||[]).map(s=>s.service_id))}<div class="error" role="alert"></div><button class="primary" type="submit">Сохранить мастера</button></form>`);
    document.querySelector('#master-form').onsubmit=e=>saveForm(e,async(data,form)=>{const selected=[...form.querySelectorAll('[name="selection"]')].filter(x=>x.checked).map(x=>Number(x.value));const payload={...data,phone:data.phone||null,email:data.email||null,service_ids:selected};delete payload.selection;if(!payload.password)delete payload.password;await api.save('masters',payload,master.user_id);close();await load();toast('Мастер сохранён');});
  }
  function serviceForm(service={}){
    if(!manage())return;
    drawer(service.service_id?'Настройки ухода':'Новая услуга',`<form id="advanced-service-form">${input('Название','title',service.title,'text','required')}<label class="field">Описание<textarea name="description">${esc(service.description||'')}</textarea></label><div class="form-grid">${input('Стоимость, ₽','price',service.price??0,'number','required min="0" step="0.01"')}${input('Длительность, минут','duration_minutes',service.duration_minutes||60,'number','required min="1" max="1440"')}</div><div class="form-grid">${input('Подготовка до, минут','buffer_before_minutes',service.buffer_before_minutes||0,'number','required min="0" max="1440"')}${input('Уборка после, минут','buffer_after_minutes',service.buffer_after_minutes||0,'number','required min="0" max="1440"')}</div><label class="field">Порода<select name="breed_id"><option value="">Для разных пород</option>${choices(state.data.breeds,'breed_id','title',service.breed_id)}</select></label><h3 class="section-title">Кто оказывает услугу</h3>${checkChoices(people(),'user_id',fullname,(service.masters||[]).map(m=>m.user_id))}${!service.service_id?`<h3 class="section-title">Расход материалов</h3><p class="sub">Количество на один уход. Пустое поле — не использовать материал.</p>${(state.data.storages||[]).map(s=>input(s.title,'consumable_'+s.item_id,'','number','min="1" step="1"')).join('')}`:`<div class="notice">Расходники: ${(service.consumables||[]).map(x=>`${esc(x.consumable?.title||'Материал #'+x.consumable_id)} — ${x.volume??'—'}`).join(', ')||'не заданы'}. Изменение норм существующей услуги не включено в текущую спецификацию.</div>`}<div class="error" role="alert"></div><button class="primary" type="submit">Сохранить услугу</button></form>`);
    document.querySelector('#advanced-service-form').onsubmit=e=>saveForm(e,async(data,form)=>{const payload={title:data.title,description:data.description||null,price:String(data.price),duration:`PT${Number(data.duration_minutes)}M`,duration_minutes:Number(data.duration_minutes),buffer_before_minutes:Number(data.buffer_before_minutes),buffer_after_minutes:Number(data.buffer_after_minutes),breed_id:Number(data.breed_id)||null,master_ids:[...form.querySelectorAll('[name="selection"]')].filter(x=>x.checked).map(x=>Number(x.value))};
      if(!service.service_id)payload.consumables=Object.entries(data).filter(([key,value])=>key.startsWith('consumable_')&&value!=='').map(([key,value])=>({consumable_id:Number(key.slice(11)),volume:Number(value)}));
      await api.save('services',payload,service.service_id);close();await load();toast('Услуга сохранена');
    });
  }
  function roleForm(user){
    if(state.role!=='admin'||user.user_id===state.userId)return;
    drawer('Доступ сотрудника',`<p class="sub">${esc(fullname(user))}</p><form id="role-form"><label class="field">Роль<select name="role">${[['client','Клиент'],['groomer','Грумер'],['manager','Менеджер'],['admin','Администратор']].map(([id,title])=>`<option value="${id}" ${user.role===id?'selected':''}>${title}</option>`).join('')}</select></label><div class="error" role="alert"></div><button class="primary" type="submit">Обновить доступ</button></form>`);
    document.querySelector('#role-form').onsubmit=e=>saveForm(e,async(data)=>{await api.setRole(user.user_id,data.role);close();await load();toast('Роль обновлена');});
  }
  async function history(pet){
    drawer('История заботы',`<h3>${esc(pet.name)}</h3><div id="pet-history-content" class="loading">Загружаем историю…</div>`);
    const target=document.querySelector('#pet-history-content');
    try{const visits=await api.petHistory(pet.pet_id);if(!target.isConnected)return;target.className='history-list';target.innerHTML=visits.length?visits.sort((a,b)=>(b.start_time||b.date).localeCompare(a.start_time||a.date)).map(v=>`<article class="history-entry"><span class="pill">${({pending:'Новая заявка',confirmed:'Подтверждено',completed:'Завершено',cancelled:'Отменено'})[v.status]||'Визит'}</span><h3>${esc(v.service_title||state.data.services.find(s=>s.service_id===v.service_id)?.title||'Уход')}</h3><p>${esc(v.date)} · ${esc(v.time?.slice(0,5))} · ${esc(v.master_name||fullname(people().find(m=>m.user_id===v.master_id)||{}))}</p></article>`).join(''):'<p class="sub">Первое знакомство ещё впереди.</p>';}catch(e){if(target.isConnected){target.className='notice';target.textContent=e.message;}}
  }
  function profile(){
    const user=state.data.users.find(u=>u.user_id===state.userId)||{};
    drawer('Ваш профиль',`<form id="own-profile-form"><div class="form-grid">${input('Имя','name',user.name,'text','required')}${input('Фамилия','surname',user.surname,'text','required')}</div>${input('Отчество','patronymic',user.patronymic)}<div class="form-grid">${input('Телефон','phone',user.phone,'tel')}${input('Email','email',user.email,'email')}</div><div class="error" role="alert"></div><button class="primary" type="submit">Сохранить профиль</button></form><section class="telegram-link-panel"><h3>МиМиРум в Telegram</h3><p class="sub">Привяжите бота к своему кабинету одноразовым кодом.</p><button class="secondary" id="generate-telegram-code">Получить код</button><div id="telegram-code-result" role="status"></div></section>`);
    document.querySelector('#own-profile-form').onsubmit=e=>saveForm(e,async(data)=>{await api.save('users',{...data,phone:data.phone||null,email:data.email||null,patronymic:data.patronymic||null},state.userId);close();await load();toast('Профиль обновлён');});
    document.querySelector('#generate-telegram-code').onclick=async(event)=>{const btn=event.currentTarget,target=document.querySelector('#telegram-code-result');btn.disabled=true;try{const result=await api.telegramCode();if(!target.isConnected)return;let href='';try{const url=new URL(result.deep_link);if(url.protocol==='https:'&&url.hostname==='t.me')href=url.href}catch{}target.innerHTML=`<div class="link-code"><b>${esc(result.code)}</b><span>Одноразовый код · действует ${Math.ceil(result.expires_in/60)} мин</span>${href?`<a class="primary" href="${esc(href)}" target="_blank" rel="noopener noreferrer">Открыть бота ↗</a>`:'<p>Отправьте этот код боту студии.</p>'}</div>`;const ttl=Math.max(0,Number(result.expires_in)||0);setTimeout(()=>{if(target.isConnected){target.innerHTML='<div class="notice">Срок действия кода истёк. Получите новый код.</div>';btn.disabled=false}},ttl*1000);}catch(e){if(target.isConnected)target.textContent=e.message;btn.disabled=false;}};
  }
  async function intervalForm(){
    try{const value=await api.slotInterval();drawer('Шаг свободных окошек',`<form id="interval-form">${input('Интервал, минут','interval_minutes',value.interval_minutes,'number','required min="1" max="1440"')}<p class="sub">Меняет сетку новых окошек. Длительность ухода остаётся прежней.</p><div class="error" role="alert"></div><button class="primary" type="submit">Сохранить</button></form>`);document.querySelector('#interval-form').onsubmit=e=>saveForm(e,async(data)=>{await api.slotInterval(Number(data.interval_minutes));close();toast('Интервал обновлён');});}catch(e){toast(e.message)}
  }
  function accessPage(){
    if(state.role!=='admin')return '<div class="empty">Управление доступом доступно администратору.</div>';
    return `<div class="page-heading"><div><h1>Роли и доступ</h1><p class="sub">Права сотрудников и клиентов. Собственную роль здесь изменить нельзя.</p></div></div><section class="panel">${state.data.users.map(u=>`<div class="request"><div><b>${esc(fullname(u))}</b><p class="sub">${esc(u.login)} · ${esc(u.role)}</p></div>${u.user_id!==state.userId?`<button class="secondary" data-access-user="${u.user_id}">Изменить роль</button>`:'<span class="pill">Ваш аккаунт</span>'}</div>`).join('')}</section>`;
  }
  function bind(){
    document.querySelectorAll('[data-access-user]').forEach(el=>el.onclick=()=>roleForm(state.data.users.find(u=>u.user_id===Number(el.dataset.accessUser))));
    document.querySelector('[data-team-new]')?.addEventListener('click',()=>masterForm());
    document.querySelectorAll('[data-team-edit]').forEach(el=>el.onclick=()=>masterForm(people().find(m=>m.user_id===Number(el.dataset.teamEdit))));
    document.querySelectorAll('[data-team-schedule]').forEach(el=>el.onclick=()=>{state.page='work-schedules';ctx.render();});
    document.querySelector('[data-schedule-new]')?.addEventListener('click',()=>scheduleForm());
    document.querySelectorAll('[data-schedule-edit]').forEach(el=>el.onclick=()=>scheduleForm(state.data['work-schedules'].find(s=>s.work_schedule_id===Number(el.dataset.scheduleEdit))));
    document.querySelector('[data-slot-interval]')?.addEventListener('click',intervalForm);
    document.querySelector('[data-own-profile]')?.addEventListener('click',profile);
  }
  return {bind,accessPage,teamPage,schedulesPage,scheduleForm,masterForm,serviceForm,roleForm,history,profile};
}
